function BetaGwentUniversalEvent(language,eventName){

  if(((eventName=="")||(language==1))){
    return eventName;
  }
  if((language==3)){
    return (eventName+"_de");
  }
  if((language==4)){
    return (eventName+"_it");
  }
  if((language==5)){
    return (eventName+"_pt_br");
  }
  return (eventName+"_en");
}
